package com.bank.cashflow;

import java.util.logging.Logger;

public class PeakWindowFinder {

    private static final Logger log = Logger.getLogger(PeakWindowFinder.class.getName());

    // Kadane's: max sum of a contiguous subarray
    public int maxSubArray(int[] flows) {
        int current = flows[0];                        // best ending at index 0
        int best = flows[0];                           // global best (handles all-negative)
        for (int i = 1; i < flows.length; i++) {
            current = Math.max(flows[i], current + flows[i]); // extend or restart
            best = Math.max(best, current);
        }
        final int answer = best;
        log.info(() -> "Peak contiguous cash-flow window sum = " + answer);
        return best;
    }
}
